import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  PlaneGeometry,
  Vector3,
  Color,
  MathUtils,
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];
  const cleanups = [];

  // Color palette
  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // Gradient backdrop
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    color: new Color(colors.background),
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // Card configuration
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardPitch = 1.85;
  const numCards = 5;
  const stripRotation = MathUtils.degToRad(-18);

  // Card titles for captions
  const cardTitles = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE',
  ];

  // Create filmstrip container
  const filmstripGroup = new Group();
  filmstripGroup.rotation.y = stripRotation;
  group.add(filmstripGroup);

  // Card meshes and state
  const cards = [];

  // Load base texture
  let baseTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    baseTexture = tex;
    // Update all card materials
    cards.forEach((card) => {
      card.material.map = baseTexture;
      card.material.needsUpdate = true;
    });
  });

  // Create 5 cards
  for (let i = 0; i < numCards; i++) {
    const xPos = (i - 2) * cardPitch; // Center at x=0

    // Card geometry with bevel effect (use plane + manual depth)
    const cardGeo = new PlaneGeometry(cardWidth, cardHeight, 1, 1);

    // Create material with PBR properties
    const cardMat = new MeshStandardNodeMaterial({
      color: new Color(colors.surface),
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      emissive: new Color(0x000000),
    });

    const cardMesh = new Mesh(cardGeo, cardMat);
    cardMesh.position.x = xPos;
    cardMesh.position.z = 0;

    // Store card state
    const cardState = {
      mesh: cardMesh,
      material: cardMat,
      index: i,
      title: cardTitles[i],
      baseScale: 0.92,
      baseOpacity: 1.0 - (i - 2) * 0.15, // Opacity gradient by distance
      targetScale: 0.92,
      targetOpacity: 1.0 - (i - 2) * 0.15,
    };

    cards.push(cardState);
    filmstripGroup.add(cardMesh);

    // Add bevel frame (thin border)
    const bevelSize = 0.025;
    const bevelFrameGeo = new PlaneGeometry(
      cardWidth + bevelSize * 2,
      cardHeight + bevelSize * 2,
      1,
      1
    );
    const bevelMat = new MeshBasicNodeMaterial({
      color: new Color(colors.ink),
    });
    const bevelFrame = new Mesh(bevelFrameGeo, bevelMat);
    bevelFrame.position.z = -0.001; // Slightly behind card
    cardMesh.add(bevelFrame);
  }

  // Create text elements
  const headlineText = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
    fontWeight: 600,
  });
  headlineText.position.set(-2.6, 1.5, 0);
  group.add(headlineText);

  const bodyText = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: colors.paper,
    align: 'left',
    fontWeight: 400,
  });
  bodyText.position.set(-2.6, -1.5, 0);
  group.add(bodyText);

  // Focused card caption (will update on focus change)
  let focusedCaptionText = null;
  let focusedCardIndex = 2; // Start with center card

  const createFocusedCaption = (index) => {
    if (focusedCaptionText) {
      group.remove(focusedCaptionText);
    }
    focusedCaptionText = ctx.fontAtlas.createText(cardTitles[index], {
      fontSize: 18,
      color: colors.accent,
      align: 'left',
      fontWeight: 700,
      letterSpacingPx: 2,
    });
    focusedCaptionText.position.set(-0.8, -1.85, 0);
    group.add(focusedCaptionText);
  };

  createFocusedCaption(focusedCardIndex);

  // Focused card underline bar (emissive red)
  const underlineGeo = new PlaneGeometry(cardWidth, 0.035);
  const underlineMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
  });
  const underlineBar = new Mesh(underlineGeo, underlineMat);
  underlineBar.position.z = 0.01;
  underlineBar.position.y = -(cardHeight / 2 + 0.1);
  cards[focusedCardIndex].mesh.add(underlineBar);

  // Update card focus states
  const updateCardFocus = (centerIndex) => {
    cards.forEach((card, idx) => {
      if (idx === centerIndex) {
        card.targetScale = 1.0;
        card.targetOpacity = 1.0;
        // Reset counter-rotation to face camera
        card.mesh.rotation.y = -stripRotation;
      } else {
        card.targetScale = 0.92;
        card.targetOpacity = 1.0 - Math.abs(idx - centerIndex) * 0.15;
        // Maintain perspective angle
        card.mesh.rotation.y = 0;
      }
    });
  };

  updateCardFocus(focusedCardIndex);

  // Parallax scroll handler
  let scrollState = {
    position: 0, // 0-4 for card indices
    velocity: 0,
    target: focusedCardIndex,
  };

  const handleScroll = (delta) => {
    scrollState.velocity = delta * 0.05; // Parallax intensity 0.5 scaled
    scrollState.target = Math.max(0, Math.min(4, scrollState.target + delta * 0.1));
  };

  const snapToCard = () => {
    const nearestCard = Math.round(scrollState.target);
    focusedCardIndex = Math.max(0, Math.min(4, nearestCard));

    if (focusedCaptionText) {
      group.remove(focusedCaptionText);
    }
    createFocusedCaption(focusedCardIndex);

    // Update underline bar
    cards.forEach((card, idx) => {
      card.mesh.children = card.mesh.children.filter(
        (c) => c !== underlineBar
      );
    });
    const newUnderlineBar = new Mesh(underlineGeo, underlineMat.clone());
    newUnderlineBar.position.z = 0.01;
    newUnderlineBar.position.y = -(cardHeight / 2 + 0.1);
    cards[focusedCardIndex].mesh.add(newUnderlineBar);

    updateCardFocus(focusedCardIndex);

    // Settle animation
    const tl = gsap.timeline();
    tl.to(
      scrollState,
      {
        target: focusedCardIndex,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      },
      0
    );
    timelines.push(tl);
  };

  // Apply parallax-scroll primitive
  const parallaxResult = ctx.primitives['parallax-scroll'](filmstripGroup, {
    intensity: 0.5,
  });
  if (parallaxResult && parallaxResult.cleanup) {
    cleanups.push(parallaxResult.cleanup);
  }

  // Animation loop
  const animationFrame = () => {
    // Smooth card position updates based on scroll
    cards.forEach((card, idx) => {
      gsap.to(card.mesh.scale, {
        x: card.targetScale,
        y: card.targetScale,
        z: card.targetScale,
        duration: 0.3,
        overwrite: false,
      });

      gsap.to(card.material, {
        opacity: card.targetOpacity,
        duration: 0.3,
        overwrite: false,
      });
    });

    requestAnimationFrame(animationFrame);
  };
  animationFrame();

  // Event handlers
  group.userData.handlers = {
    scroll: (e) => {
      handleScroll(e.deltaY > 0 ? 1 : -1);
      snapToCard();
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    cleanups.forEach((fn) => fn?.());
    // Dispose geometries and materials
    cards.forEach((card) => {
      card.mesh.geometry.dispose();
      card.material.dispose();
    });
    backdropGeo.dispose();
    backdropMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
  };

  return group;
}
